 final FishingProofChecks proof;FishingMod m;ServerPlayerEntity p;FishingMod.Encounter encounter;EmptyPokeBallEntity ball;int stage,started;Set<EmptyPokeBallEntity.CaptureState> seen=EnumSet.noneOf(EmptyPokeBallEntity.CaptureState.class);Set<UUID> party,pc;
